SELECT name AS full_name, country AS country_code
FROM customers
WHERE trim(name) = 'Walsh' OR trim(name) LIKE '% Walsh';

SELECT name
FROM products
WHERE price_minor = (SELECT MIN(price_minor) FROM products);

SELECT COALESCE(SUM((p.price_minor - oi.unit_price_minor) * oi.quantity), 0) / 100.0 AS total_discount_dollars
FROM order_items AS oi
JOIN products AS p ON p.id = oi.product_id;

SELECT COALESCE(SUM(
    o.shipping_minor + COALESCE((
        SELECT SUM(oi.quantity * oi.unit_price_minor)
        FROM order_items AS oi
        WHERE oi.order_id = o.id
    ), 0)
), 0) / 100.0 AS total_charge_dollars
FROM orders AS o
WHERE o.status = 'pending_payment';

